package io.github.ningpp.compat;

/**
 * Replacement for System.Threading.Barrier (generated by CSharpToJava converter).
 * <p>
 * The converter lowers Task/TaskFactory to synchronous execution, so a barrier that
 * really waited for every participant would never be released and the generated
 * concurrency tests would deadlock. SignalAndWait therefore only records the arrival —
 * advancing the phase once every participant has arrived — and returns immediately.
 */
public class Barrier {

    private final int participantCount;
    private int arrivedParticipants;
    private long currentPhaseNumber;

    /**
     * Creates a barrier for the given number of participants.
     *
     * @param participantCount The number of participants in the barrier.
     */
    public Barrier(int participantCount) {
        if (participantCount < 0) {
            throw new ArgumentOutOfRangeException("participantCount");
        }
        this.participantCount = participantCount;
    }

    /**
     * C# Barrier.ParticipantCount.
     *
     * @return The number of participants in the barrier.
     */
    public int getParticipantCount() {
        return participantCount;
    }

    /**
     * C# Barrier.CurrentPhaseNumber.
     *
     * @return The number of the current phase, starting at 0.
     */
    public long getCurrentPhaseNumber() {
        return currentPhaseNumber;
    }

    /**
     * C# Barrier.SignalAndWait() — records the arrival and returns without blocking.
     */
    public void signalAndWait() {
        arrive();
    }

    /**
     * C# Barrier.SignalAndWait(int millisecondsTimeout) — records the arrival and
     * returns true immediately instead of waiting for the other participants.
     *
     * @param timeout The timeout in milliseconds; ignored because the barrier never
     *        blocks.
     * @return Always true.
     */
    public boolean signalAndWait(long timeout) {
        arrive();
        return true;
    }

    /**
     * Records one arrival and starts the next phase once every participant has
     * arrived.
     */
    private synchronized void arrive() {
        arrivedParticipants++;
        if (participantCount > 0 && arrivedParticipants >= participantCount) {
            arrivedParticipants = 0;
            currentPhaseNumber++;
        }
    }

    /**
     * C# Barrier.ToString().
     *
     * @return A description of the barrier state.
     */
    @Override
    public String toString() {
        return "Barrier [participants=" + participantCount
            + ", phase=" + currentPhaseNumber
            + ", arrived=" + arrivedParticipants + "]";
    }
}
